    sources=[dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type=k,primary_source=True,authority_tier=2 if k=='first-party-doc' else 1,accessed_at='2026-09-09T21:28:16Z',relevance=r) for i,(t,o,u,v,k,r) in enumerate(rows,1)]
