    sr=[refs(1,2,5),refs(1,2,3),refs(3,4,6),refs(4,5),refs(1,2,5),refs(2,3,5),refs(3,6),refs(2,3,6),refs(3,4,6,7),refs(2,3,6),refs(3,5,6),refs(1,2,3,4,5,6,7)]
    kinds=[['identity','classification','evidence'],['composition','spatial','relationship'],['requirement','provenance','temporal'],['state','authority','constraint'],['relationship','classification','constraint'],['ownership','authority','process'],['measurement','relationship','decision'],['evidence','measurement','exception'],['lifecycle','temporal','exception'],['state','process','constraint'],['ownership','access','retention'],['interoperability','quality','validation']]
