            questions=re.findall(r'(?m)^\d\. (.+\?)$',qs); groups=re.findall(r'([a-zA-Z]+)\{([^}]+)\}',answers)
            assert len(questions)==len(groups)==3
            lid=ids[n]; desc='Scoped supplier/partner '+name.lower()+' assertions, with source and authority limits. Record changes do not execute procurement, payments or exclusion.'
            fields=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed answer fields: '+members+'. Preserve explicit unknowns and evidence attribution; executable nested constraints remain deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr[n]) for key,members in groups]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr[n],questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[n][i],answer_data=[fields[i]['id']]) for i,q in enumerate(questions)],data_elements=fields,artifacts=[dict(id=lid+'-artifact',name=name+' evidence artifact',description='Minimal revisioned supplier assertion and authorized evidence references; no bank details, credentials or unnecessary confidential assessment payloads.',media_or_form=['text/markdown','application/json','application/yaml','external reference'],serial=True,identity_strategy='Master-qualified ID or Dimension UUID, immutable revision and digest; timestamp is not unique identity.',source_refs=sr[n])],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr[n],findings=[finding])); n+=1
