    model=dict(registry_id='vr.wm-org-015',model_id='WM-ORG-015',name='Supplier / Partner Relationship',entry_kind='relationship',purpose='Describe qualification, risk and commercial status of a buyer- or collaboration-scoped supplier/partner relationship.',scope_statement='Relationship record tying an owner to a counterparty and supplied capability; not party identity, purchase transaction or legal partnership determination. Preserve role, approval and source assessment scope.',in_scope=['Buyer/collaboration scope, participant roles and supplied capabilities','Qualification evidence, attributed approval, commercial references and responsibilities','Risk/performance context, change/exit continuity and governed exchange'],out_of_scope=['Party, bank account and credential master data','Execution of onboarding, payments, purchasing, outreach or supplier exclusion','Universal approval states, legal control, sanctions adjudication or industry-wide risk scoring'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=c) for a,b,c in [('Organization master','Multiple scoped supplier roles can reference one legal party; never remaster it here.',refs(1,2,5)),('Procurement and contracts','Award suppliers, agreements and transaction authority are referenced, not replaced by generic approved status.',refs(1,2,4)),('Financial account and payee','Seller, accounting supplier and payee can differ; relationship editing must not redirect funds.',refs(2)),('Inter-organizational partnership','Role label and supply dependency do not establish legal control or a universal legal partnership.',refs(1,3,5))]])
    services=dict(
      dimension=dict(owner_package_requirements=['Declare relationship owner, steward and delegated reviewers.','Identify party, qualification, contract, risk and transaction masters.','Bind access, evidence, retention and cross-Dimension disclosure policies.'],namespace_guidance='Qualify relationship ID by master and buyer/collaboration scope; party names or tax IDs alone do not identify a relationship.',registry_links=['Supplier/partner relationship registry','Party and capability references','Qualification, agreement and assessment registries','Policy, event and revision registries']),
      canon_and_patch=dict(canonicalization_rules=['Preserve role, buying scope, source state scheme and evidence freshness.','Keep declaration, assessment, approval and transaction authorization distinct.'],patch_rules=['Add namespaced profiles pinned to base version and digest.','Append corrections under expected-head checks; preserve disputed assertions and prior qualified scope.'],compatibility_rules=['Changed role, qualification or risk scale semantics require explicit migration and loss reporting.','Do not map expired or unknown evidence to approved, or group membership to authority.']),
      artifact_rules=dict(identity_priority=['Authoritative master-qualified identifier','Governed issuer-qualified URI','Dimension-issued UUID'],timestamp_rule='RFC 3339 with seconds and explicit offset or Z for precise observed/recorded instants; retain uncertain or date-only source effects separately.',serial_naming_rule='Supplier artifact-kind prefix plus escaped stable ID and revision; do not expose personal names or account details in paths.',integrity_rule='Check exact-byte digest, source revision and expected head; integrity does not prove qualification or risk truth.'),
      policies=['Registration is not qualification and qualification is not authorization for every transaction.','Assessment labels are attributed, time-scoped evidence; do not execute automatic exclusion or infer sensitive traits.','Relationship updates do not cancel obligations, change payees or send communications.','Minimize private evidence and keep separate master authority and access for each field.'],
      crud=dict(read=['Read owner purpose, scope, source scheme, evidence freshness and assurance before relying on status.'],create=['Create authorized minimal relationship assertions with typed references and explicit unknowns.'],update=['Append approved record changes under expected-head and scope checks; preserve competing source claims and lineage.'],delete=['Apply authorized retention/correction with justified holds; local tombstone does not terminate contract or erase obligations.']),
      roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Sets purpose and delegation.'),('Relationship steward','Maintains scope, mastership and evidence review.'),('Contributor','Records authorized minimal supplier claims and references.'),('Reviewer','Assesses evidence quality, scope and disputed status.'),('Custodian','Enforces disclosure, retention and revision integrity.')]],
      access=dict(default_rule='Deny unless purpose- and field-specific access is delegated; supplier registration grants no operational access.',scopes=['bundle','layer','finding','artifact'],exceptions=['Explicit time-limited delegated exceptions name approving role, fields and purpose.'],audit_requirements=['Record actor, purpose, scope, decision and revision without confidential payloads or credentials.']),
      agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension purpose, authority and mastership','Pinned model, counterparty role and buyer scope','Qualification, assessment, commercial references and valid time','Safe record operations, validation, extensions and retention']))
    frows=[
      ('resolve-supplier','Resolve scoped relationship','Identify a relationship without merging the party master.',['Qualified ID or candidates','Buyer/collaboration scope'],['Relationship reference or explicit ambiguity'],['Read permission','No name-only identity merge'],['Read-only lookup, no supplier approval'],refs(1,2,5)),
      ('record-qualification','Record qualification evidence','Append an attributed qualification claim or assessment.',['Criteria and evidence refs','Attribution and validity','Expected head'],['New assertion or conflict'],['Write scope','Source and criteria declared'],['Local record only, no certification or transaction authorization created'],refs(3,4,6)),
      ('record-authorization','Revise attributed authorization','Record a decision made by the appropriate master.',['Decision reference','Scope and source scheme','Expected head'],['Attributed successor status or unknown'],['Decision authority verified','Write delegation'],['No approval execution, purchase, payment or access grant'],refs(4,5,6)),
      ('link-supplier-masters','Link commercial masters','Connect typed procurement and role references.',['Agreement/award refs','Party-role mapping','Expected revision'],['Traceable links or unresolved references'],['Target kind checked','Reference disclosure permitted'],['No contract change or payee redirection'],refs(1,2,5)),
      ('record-supplier-review','Record change and exit context','Preserve review triggers and continuity responsibilities.',['Change evidence','Review/exit decision refs','Valid and recorded time'],['Revision with outstanding-master references'],['Write scope','Expected-head check','No automatic approval transfer'],['Local context only; no exclusion, cancellation or service cut-off'],refs(3,4,6,7)),
      ('export-supplier','Export permitted projection','Map minimized fields to a declared target profile.',['Authorized fields','Pinned target profile','Loss definitions'],['Projection or refusal with losses'],['Disclosure authority','Role and approval semantics checked'],['No external publication/transmission without authority; incompatible meaning yields refusal'],refs(1,2,3,4,5))]
    functions=[dict(id=i,name=n,description=d,inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,d,a,b,c,e,s in frows]
