    dims=[('identity','Master and buyer/collaboration scoped relationship.'),('classification','Declared supplier/partner role scheme.'),('direct properties','Supply scope, attributed state and qualification validity.'),('recognition','Evidence distinguishes registration, qualification and approval.'),('capabilities','Six bounded record functions, not procurement operations.'),('lifecycle','Change, suspension, exit and reinstatement context.'),('relationships','Typed party, sub-tier, agreement and payee references.'),('temporal','Effective, observed and recorded precision separated.'),('provenance','Declared versus assessed evidence and revision lineage.'),('ownership','Relationship stewardship distinct from decision authority.'),('access','Purpose-scoped field permissions and minimized disclosure.'),('retention','Correction and justified history under policy.'),('interoperability','Pinned source role mapping and loss-aware exchange.')]
